import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { ApexPainter } from 'apexify.js';

const outputDir = process.env.APEXIFY_EXAMPLE_OUTPUT_DIR;
if (!outputDir) throw new Error('APEXIFY_EXAMPLE_OUTPUT_DIR is required.');

const painter = new ApexPainter({ type: 'buffer' });
const canvas = await painter.createCanvas({ width: 320, height: 180, colorBg: '#0f172a' });
if (!Buffer.isBuffer(canvas.buffer)) throw new Error('Expected createCanvas() to expose a PNG Buffer.');

await mkdir(outputDir, { recursive: true });
await writeFile(join(outputDir, 'canvas-basic.png'), canvas.buffer);
console.log(JSON.stringify({ example: 'node.canvas.basic', format: 'png', width: 320, height: 180, bytes: canvas.buffer.length }));

import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { ApexPainter } from 'apexify.js';

const outputDir = process.env.APEXIFY_EXAMPLE_OUTPUT_DIR;
if (!outputDir) throw new Error('APEXIFY_EXAMPLE_OUTPUT_DIR is required.');

const painter = new ApexPainter({ type: 'buffer' });
const data = [
  { label: 'Docs', value: 72, xStart: 0, xEnd: 1, color: '#6366f1' },
  { label: 'API', value: 58, xStart: 1, xEnd: 2, color: '#8b5cf6' },
  { label: 'Gallery', value: 50, xStart: 2, xEnd: 3, color: '#ec4899' },
];
const png = await painter.createChart('bar', data, { dimensions: { width: 480, height: 320 } });
if (!Buffer.isBuffer(png)) throw new Error('Expected createChart() to return a PNG Buffer.');

await mkdir(outputDir, { recursive: true });
await writeFile(join(outputDir, 'chart-bar.png'), png);
console.log(JSON.stringify({ example: 'node.chart.bar', format: 'png', width: 480, height: 320, bytes: png.length }));

import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { ApexPainter } from 'apexify.js';

const outputDir = process.env.APEXIFY_EXAMPLE_OUTPUT_DIR;
if (!outputDir) throw new Error('APEXIFY_EXAMPLE_OUTPUT_DIR is required.');

const painter = new ApexPainter({ type: 'buffer' });
const first = await painter.createCanvas({ width: 96, height: 64, colorBg: '#312e81' });
const second = await painter.createCanvas({ width: 96, height: 64, colorBg: '#be185d' });
const gif = await painter.createGIF(
  [
    { buffer: first.buffer, duration: 120 },
    { buffer: second.buffer, duration: 120 },
  ],
  { outputFormat: 'buffer', width: 96, height: 64, repeat: -1, quality: 20, skipResizeWhenDimensionsMatch: true },
);
if (!Buffer.isBuffer(gif)) throw new Error('Expected createGIF({ outputFormat: buffer }) to return a GIF Buffer.');

await mkdir(outputDir, { recursive: true });
await writeFile(join(outputDir, 'animation.gif'), gif);
await writeFile(join(outputDir, 'poster.png'), first.buffer);
console.log(JSON.stringify({ example: 'node.gif.basic', format: 'gif', width: 96, height: 64, bytes: gif.length, frames: 2 }));

import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { ApexPainter } from 'apexify.js';
import { reportEntries } from './report-data.js';

const outputDir = process.env.APEXIFY_EXAMPLE_OUTPUT_DIR;
if (!outputDir) throw new Error('APEXIFY_EXAMPLE_OUTPUT_DIR is required.');

const painter = new ApexPainter({ type: 'buffer' });
const chartData = reportEntries.map((entry, index) => ({
  label: entry.label,
  value: entry.value,
  xStart: index,
  xEnd: index + 1,
  color: entry.color,
}));
const png = await painter.createChart('bar', chartData, { dimensions: { width: 640, height: 360 } });
const highest = [...reportEntries].sort((a, b) => b.value - a.value)[0]?.label ?? '';
const summary = { total: reportEntries.reduce((sum, entry) => sum + entry.value, 0), highest, entries: reportEntries.length };

await mkdir(outputDir, { recursive: true });
await writeFile(join(outputDir, 'report.png'), png);
await writeFile(join(outputDir, 'summary.json'), `${JSON.stringify(summary, null, 2)}\n`);
console.log(JSON.stringify({ example: 'node.integration.report', outputs: ['report.png', 'summary.json'], summary }));

export interface ReportEntry {
  label: string;
  value: number;
  color: string;
}

export const reportEntries: ReportEntry[] = [
  { label: 'Docs', value: 80, color: '#6366f1' },
  { label: 'API', value: 60, color: '#8b5cf6' },
  { label: 'Gallery', value: 40, color: '#ec4899' },
];
